cat <<'EOF' > app/javascript/helpers/i18n_helpers.js
import { getMetaContent } from "helpers/meta_helpers"

let cachedRaw
let cachedTranslations = {}

export function getI18n() {
  const raw = getMetaContent("i18n")
  if (raw !== cachedRaw) {
    cachedRaw = raw
    try {
      cachedTranslations = raw ? JSON.parse(raw) : {}
    } catch {
      cachedTranslations = {}
    }
  }
  return cachedTranslations
}

export function t(path, interpolations = {}) {
  let value = path.split(".").reduce((obj, key) => obj?.[key], getI18n())
  if (typeof value !== "string") return path

  for (const [ key, replacement ] of Object.entries(interpolations)) {
    value = value.replaceAll(`%{${key}}`, replacement)
  }
  return value
}

export function intlLocale() {
  return getI18n().intl_locale || document.documentElement.lang || "en-US"
}
EOF

cat <<'EOF' > app/javascript/helpers/text_helpers.js
import { getI18n } from "helpers/i18n_helpers"

export function isMultiLineString(string) {
  return /\r|\n/.test(string)
}

export function normalizeFilteredText(string) {
  return string
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Remove diacritics
}

export function filterMatches(text, potentialMatch) {
  return normalizeFilteredText(text).includes(normalizeFilteredText(potentialMatch))
}

export function toSentence(array, options = {}) {
  const i18nSentence = getI18n().sentence || {}
  const defaultConnectors = {
    words_connector: i18nSentence.words_connector ?? ", ",
    two_words_connector: i18nSentence.two_words_connector ?? " and ",
    last_word_connector: i18nSentence.last_word_connector ?? ", and "
  }

  const connectors = { ...defaultConnectors, ...options }

  if (array.length === 0) {
    return ""
  }

  if (array.length === 1) {
    return array[0]
  }

  if (array.length === 2) {
    return array.join(connectors.two_words_connector)
  }

  return array.slice(0, -1).join(connectors.words_connector) + connectors.last_word_connector + array[array.length - 1]
}

export function toChoiceSentence(array) {
  const i18nChoice = getI18n().choice_sentence || {}
  return toSentence(array, {
    words_connector: i18nChoice.words_connector ?? ", ",
    two_words_connector: i18nChoice.two_words_connector ?? " or ",
    last_word_connector: i18nChoice.last_word_connector ?? ", or "
  })
}
